window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II et phrases avec wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si j'étais toi, je …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La réalité d'Eva – les souhaits d'Eva. Complétez : würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Elle aimerait pourtant être plus grande.","why":"*grösser sein* : la forme de souhait de *sein* est **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Elle aimerait pourtant bien parler espagnol.","why":"Un infinitif se trouve à la fin (*sprechen*), donc le souhait se forme avec **würde** + infinitif.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Elle préférerait pourtant travailler comme guide touristique.","why":"Infinitif à la fin (*arbeiten*) → **würde** + infinitif. *lieber* = plutôt.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Elle aimerait pourtant avoir un grand appartement.","why":"*eine Wohnung haben* : la forme de souhait de *haben* est **hätte**. Pas besoin d'infinitif.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"À quoi pensent ces personnes ?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque image à une expression de l'encadré.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si je ne devais pas travailler, je serais assis au jardin en ce moment.","why":"L'image 1 le montre en train de travailler, puis rêvant sur une chaise longue. Après une subordonnée en *wenn*, la principale commence par le verbe (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si j'avais une voiture, je ne devrais pas faire du vélo sous la pluie.","why":"Il fait du vélo sous la pluie ; une voiture lui éviterait cela. *müsste* est le Konjunktiv II de *müssen*. *Velo* est le mot suisse pour *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si le bus n'avait pas de retard, je serais à l'heure au bureau.","why":"Un bus en retard la met en retard au travail. *wäre* est le Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a : commencez par la principale, puis la subordonnée en wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Je ne devrais pas faire du vélo sous la pluie si j'avais une voiture.","why":"D'abord la principale, puis la subordonnée en *wenn*. Dans la subordonnée en *wenn*, le verbe (*hätte*) va à la fin.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Je serais à l'heure au bureau si le bus n'avait pas de retard.","why":"Même schéma : principale, virgule, *wenn* … verbe à la fin (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec les mots de l'encadré. Chaque mot est utilisé une fois ; les mots barrés sont utilisés dans l'exemple.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Je ferais certaines choses autrement si j'étais la cheffe de notre entreprise.","why":"*machen* à la fin → **würde** + infinitif. *Chefin sein* → **wäre**, à la fin de la subordonnée en *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si j'étais Marco, je ferais absolument une formation professionnelle.","why":"*Marco sein* → **wäre** (comme *Wenn ich du wäre …*). La principale a l'infinitif *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si je pouvais décider librement, je travaillerais dans une petite entreprise.","why":"*frei entscheiden können* → **könnte** à la fin de la subordonnée en *wenn*. Principale avec *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si nous avions des enfants, je ne devrais travailler qu'à mi-temps.","why":"*Kinder haben* avec *wir* → **hätten**. L'encadré laisse **müsste** pour le dernier trou.","source":"k2","check":"*müsste* et *würde* sont tous deux corrects en b, c et e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* est tout aussi bon). L'encadré indique seulement quels trois trous reçoivent *würde* et lequel reçoit *müsste* ; ce corrigé donne la répartition la plus probable. Demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Je dois me dépêcher à cause de mon travail.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Réécrivez les réponses avec weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Parce que mon amie n'est pas ponctuelle.","why":"*wegen* + nom devient *weil* + une proposition avec un verbe ; le verbe (*ist*) va à la fin.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Parce qu'il fait mauvais.","why":"*des schlechten Wetters* → *das Wetter ist schlecht* ; après *weil*, le verbe va à la fin.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Parce que j'ai un rendez-vous important.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusatif après *haben*) ; verbe à la fin.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Complétez : wegen – weshalb – weil – deswegen – denn. Un mot peut être utilisé plusieurs fois.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Je le comprends mal à cause de sa prononciation.","why":"Un nom suit (*seiner Aussprache*, génitif), pas une proposition → la préposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un jour, j'aimerais bien aller en Italie, car j'aimerais voir la mer.","why":"Le verbe reste en 2e position après le trou (*ich möchte*) → **denn**. Avec *weil*, il irait à la fin.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Je dois améliorer ma compréhension orale, c'est pourquoi je regarde beaucoup de films.","why":"La deuxième partie est la conséquence, et le verbe vient juste après le trou (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mes enfants ont vite appris l'allemand parce qu'à l'école enfantine, ils sont toujours avec des enfants suisses.","why":"Le verbe est à la fin (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Pourquoi écris-tu les mots sur des petites cartes ?","why":"Il faut un mot interrogatif : **Weshalb** signifie *warum* (pourquoi)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Ma sœur parle déjà presque couramment l'allemand, c'est pourquoi elle peut m'aider à apprendre l'allemand.","why":"Conséquence, et le verbe vient juste après le trou (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Au cours de langue. Complétez : weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Je n'ai pas pu faire le dernier exercice parce que je ne l'ai pas compris.","why":"Le verbe est à la fin (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"Il n'y avait personne à l'inscription. C'est pourquoi je suis rentré à la maison.","why":"Une nouvelle phrase qui donne la conséquence, avec le verbe juste après le trou (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"En raison de mes bonnes notes, je n'ai pas dû passer de test au début du cours.","why":"Un groupe nominal suit (*meiner guten Noten*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Il y a un cours de langue supplémentaire parce que de très nombreux participants se sont inscrits.","why":"Le verbe est à la fin (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Hier, je n'ai malheureusement pas pu venir au cours à cause de mon mal de dents.","why":"Un groupe nominal suit (*meiner Zahnschmerzen*, génitif pluriel) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Qui trouve les meilleures excuses ? Choisissez une situation et écrivez. Les réponses modèles ne sont chaque fois qu'une possibilité parmi d'autres.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Malheureusement, je n'ai pas pu ranger la cuisine parce que j'ai soudain eu très mal au dos. J'ai dû m'allonger. C'est pourquoi j'ai regardé un film.","why":"Emploie *weil* (verbe à la fin : *hatte*) et *Deswegen* (verbe juste après : *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"À cause d'une grippe, je ne suis pas allé à l'examen final. J'avais beaucoup de fièvre, c'est pourquoi je suis resté au lit.","why":"Emploie *wegen* + génitif (*einer Grippe*) et *deswegen* + verbe (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Je suis vraiment désolé ! Malheureusement, je suis arrivé en retard, car il y avait un accident sur l'autoroute. À cause de l'embouteillage, j'ai perdu deux heures.","why":"*denn* garde le verbe en 2e position (*war*). *wegen des Staus* : génitif de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}]}];
